#include <xcb/xcb.h>
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void){setvbuf(stdout,NULL,_IOLBF,0);int screen;xcb_connection_t*c=xcb_connect(NULL,&screen);assert(!xcb_connection_has_error(c));xcb_screen_iterator_t i=xcb_setup_roots_iterator(xcb_get_setup(c));while(screen--)xcb_screen_next(&i);xcb_window_t w=xcb_generate_id(c);uint32_t mask[]={0x20c040,XCB_EVENT_MASK_EXPOSURE|XCB_EVENT_MASK_KEY_PRESS|XCB_EVENT_MASK_KEY_RELEASE|XCB_EVENT_MASK_BUTTON_PRESS|XCB_EVENT_MASK_BUTTON_RELEASE|XCB_EVENT_MASK_POINTER_MOTION|XCB_EVENT_MASK_STRUCTURE_NOTIFY|XCB_EVENT_MASK_FOCUS_CHANGE};xcb_create_window(c,XCB_COPY_FROM_PARENT,w,i.data->root,0,0,240,160,0,XCB_WINDOW_CLASS_INPUT_OUTPUT,i.data->root_visual,XCB_CW_BACK_PIXEL|XCB_CW_EVENT_MASK,mask);const char*title="Trames desktop acceptance";xcb_change_property(c,XCB_PROP_MODE_REPLACE,w,XCB_ATOM_WM_NAME,XCB_ATOM_STRING,8,strlen(title),title);xcb_intern_atom_reply_t*p=xcb_intern_atom_reply(c,xcb_intern_atom(c,0,12,"WM_PROTOCOLS"),NULL),*d=xcb_intern_atom_reply(c,xcb_intern_atom(c,0,16,"WM_DELETE_WINDOW"),NULL);assert(p&&d);xcb_change_property(c,XCB_PROP_MODE_REPLACE,w,p->atom,XCB_ATOM_ATOM,32,1,&d->atom);xcb_map_window(c,w);xcb_flush(c);int done=0;while(!done){xcb_generic_event_t*e=xcb_wait_for_event(c);assert(e);switch(e->response_type&0x7f){case XCB_KEY_PRESS:case XCB_KEY_RELEASE:{xcb_key_press_event_t*k=(void*)e;printf("key %u %u\n",k->detail-8,(e->response_type&0x7f)==XCB_KEY_PRESS);if(k->detail==38&&(e->response_type&0x7f)==XCB_KEY_PRESS){uint32_t color=0xc04020;xcb_change_window_attributes(c,w,XCB_CW_BACK_PIXEL,&color);xcb_clear_area(c,0,w,0,0,0,0);}break;}case XCB_BUTTON_PRESS:case XCB_BUTTON_RELEASE:{xcb_button_press_event_t*b=(void*)e;printf("button %u %u\n",b->detail,(e->response_type&0x7f)==XCB_BUTTON_PRESS);if(b->detail==1&&(e->response_type&0x7f)==XCB_BUTTON_PRESS){uint32_t color=0x2040c0;xcb_change_window_attributes(c,w,XCB_CW_BACK_PIXEL,&color);xcb_clear_area(c,0,w,0,0,0,0);}break;}case XCB_CONFIGURE_NOTIFY:{xcb_configure_notify_event_t*g=(void*)e;printf("size %u %u\n",g->width,g->height);break;}case XCB_FOCUS_IN:puts("focus-in");break;case XCB_FOCUS_OUT:puts("focus-out");break;case XCB_CLIENT_MESSAGE:if(((xcb_client_message_event_t*)e)->data.data32[0]==d->atom)done=1;break;default:break;}free(e);xcb_flush(c);}puts("desktop-done");xcb_destroy_window(c,w);xcb_flush(c);free(p);free(d);xcb_disconnect(c);return 0;}
